const fs=require('node:fs');
const p='docs/architecture/ADR-28A-LU-OWNER-DECISION-BATCH-2026-09-26.md';
const V=m=>{console.error('LU_OWNER_DECISION_RECORD_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('LU_OWNER_DECISION_RECORD_HARNESS_ERROR: '+m);process.exit(2)};
try{
 let s; try{s=fs.readFileSync(p,'utf8')}catch(e){if(e&&e.code==='ENOENT')V('owner decision record absent');H(String(e))}
 const req=process.argv[1].split('||'); const missing=req.filter(x=>!s.includes(x)); if(missing.length)V('missing bindings: '+missing.join(' | '));
 console.log('LU_OWNER_DECISION_RECORD_OK');
}catch(e){H(e&&e.stack?e.stack:String(e))}

